const managedConfig=req=>{admin(req);const cfg=managed[req.params.table];if(!cfg)throw new ApiError(404,'Unknown collection');return cfg;};

const instructorImageTypes=new Set(['image/jpeg','image/png','image/webp','image/avif']);
function checkInstructorImage(file){if(!file)throw new ApiError(422,'Choose an instructor image');if(!instructorImageTypes.has(file.mimetype))throw new ApiError(422,'Use a JPEG, PNG, WebP, or AVIF image');}
function instructorLinks(body){const links={};for(const key of ['linkedin','github','website']){const value=body[`${key}_url`]?.trim();if(!value)continue;let parsed;try{parsed=new URL(value);}catch{throw new ApiError(422,`Enter a complete URL for ${key}`);}if(!['http:','https:'].includes(parsed.protocol))throw new ApiError(422,`Use an https:// or http:// URL for ${key}`);links[key]=parsed.toString();}return links;}
const instructorFields={name:z.string().trim().min(2).max(150),designation:z.string().trim().max(150).default(''),details:z.string().trim().max(10000).default(''),linkedin_url:z.string().trim().max(500).default(''),github_url:z.string().trim().max(500).default(''),website_url:z.string().trim().max(500).default(''),remove_image:z.enum(['true','false']).optional()};
app.post('/admin/instructors',upload.single('image'),run(async req=>{admin(req);checkInstructorImage(req.file);const instructor=z.object(instructorFields).strict().parse(req.body);const socialLinks=instructorLinks(instructor);return(await query('INSERT INTO instructors(name,designation,image_blob,image_mime_type,details,social_links) VALUES($1,$2,$3,$4,$5,$6) RETURNING id,name,designation,details,social_links,image_mime_type,(image_blob IS NOT NULL) has_image,created_at',[instructor.name,instructor.designation,req.file.buffer,req.file.mimetype,instructor.details,JSON.stringify(socialLinks)])).rows[0];}));
app.patch('/admin/instructors/:id',upload.single('image'),run(async req=>{admin(req);const id=uuid(req.params.id);const body=z.object({...instructorFields,name:instructorFields.name.optional(),designation:instructorFields.designation.optional(),details:instructorFields.details.optional(),linkedin_url:instructorFields.linkedin_url.optional(),github_url:instructorFields.github_url.optional(),website_url:instructorFields.website_url.optional()}).strict().parse(req.body);if(req.file)checkInstructorImage(req.file);const fields=[],values=[];const add=(field,value)=>{fields.push(`${field}=$${values.length+1}`);values.push(value);};if(body.name!==undefined)add('name',body.name);if(body.designation!==undefined)add('designation',body.designation);if(body.details!==undefined)add('details',body.details);if(['linkedin_url','github_url','website_url'].some(key=>body[key]!==undefined))add('social_links',JSON.stringify(instructorLinks({...body,linkedin_url:body.linkedin_url||'',github_url:body.github_url||'',website_url:body.website_url||''})));if(req.file){add('image_blob',req.file.buffer);add('image_mime_type',req.file.mimetype);}else if(body.remove_image==='true'){add('image_blob',null);add('image_mime_type',null);}if(!fields.length)throw new ApiError(422,'Update a profile field or choose a new image');values.push(id);const result=await query(`UPDATE instructors SET ${fields.join(',')} WHERE id=$${values.length} RETURNING id,name,designation,details,social_links,image_mime_type,(image_blob IS NOT NULL) has_image,created_at`,values);if(!result.rowCount)throw new ApiError(404,'Instructor not found');return result.rows[0];}));
app.delete('/admin/instructors/:id',run(async req=>{admin(req);const id=uuid(req.params.id);const courses=Number((await query('SELECT count(*) FROM courses WHERE instructor_id=$1',[id])).rows[0].count);const result=await query('DELETE FROM instructors WHERE id=$1 RETURNING id',[id]);if(!result.rowCount)throw new ApiError(404,'Instructor not found');return{deleted:true,unassigned_courses:courses};}));

app.get('/admin/settings',run(async req=>{admin(req);const rows=(await query("SELECT key,value FROM platform_settings WHERE key IN ('registration_open','content_review_required')")).rows;const values={registration_open:true,content_review_required:true};for(const row of rows)values[row.key]=row.value===true;return values;}));
app.patch('/admin/settings',run(async req=>{admin(req);const settings=z.object({registration_open:z.boolean().optional(),content_review_required:z.boolean().optional()}).strict().refine(value=>Object.keys(value).length>0).parse(req.body);const descriptions={registration_open:'Allow public self-registration.',content_review_required:'Require admin approval before creators publish courses, contests, webinars or jobs.'};for(const[key,value]of Object.entries(settings))await query('INSERT INTO platform_settings(key,value,description,updated_by) VALUES($1,$2::jsonb,$3,$4) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,description=EXCLUDED.description,updated_by=EXCLUDED.updated_by,updated_at=now()',[key,JSON.stringify(value),descriptions[key],req.user.sub]);return settings;}));
app.get('/admin/overview',run(async req=>{admin(req);const stats=await one(`SELECT (SELECT count(*) FROM users) total_users,(SELECT count(*) FROM users WHERE role='learner') learners,(SELECT count(*) FROM users WHERE role='hirer') hirers,(SELECT count(*) FROM users WHERE account_status='active') active_users,(SELECT count(*) FROM courses) courses,(SELECT count(*) FROM courses WHERE status='published') published_courses,(SELECT count(*) FROM courses WHERE status='draft') draft_courses,(SELECT count(*) FROM contests) contests,(SELECT count(*) FROM contests WHERE status='published') published_contests,(SELECT count(*) FROM webinars) webinars,(SELECT count(*) FROM webinars WHERE status IN('scheduled','live')) active_webinars,(SELECT count(*) FROM jobs) jobs,(SELECT count(*) FROM jobs WHERE status='open') open_jobs,(SELECT count(*) FROM reported_showcase_posts WHERE status IN('pending','reviewing')) open_reports`);const activity=(await query(`SELECT * FROM(SELECT id::text id,'user'::text kind,'New account registered'::text title,name::text detail,created_at occurred_at FROM users UNION ALL SELECT id::text id,'course'::text kind,'Course created'::text title,title::text detail,created_at occurred_at FROM courses UNION ALL SELECT id::text id,'contest'::text kind,'Contest created'::text title,name::text detail,created_at occurred_at FROM contests UNION ALL SELECT id::text id,'webinar'::text kind,'Webinar created'::text title,name::text detail,created_at occurred_at FROM webinars UNION ALL SELECT id::text id,'job'::text kind,'Job posted'::text title,title::text detail,created_at occurred_at FROM jobs UNION ALL SELECT id::text id,'report'::text kind,'Post reported'::text title,reason::text detail,created_at occurred_at FROM reported_showcase_posts) activity ORDER BY occurred_at DESC LIMIT 12`)).rows;return{stats,activity};}));
app.get('/admin/:table',run(async req=>{const cfg=managedConfig(req);const[limit,offset]=paging(req);const values=[];const where=[cfg.where||'TRUE'];const add=value=>{values.push(value);return`$${values.length}`;};const search=String(req.query.q||'').trim().slice(0,200);if(search&&cfg.search?.length){const key=add(`%${search}%`);where.push(`(${cfg.search.map(field=>`${field}::text ILIKE ${key}`).join(' OR ')})`);}if(req.query.status){if(!cfg.statusField||!cfg.statusValues?.includes(String(req.query.status)))throw new ApiError(422,'Invalid status filter');where.push(`${cfg.statusField}::text=${add(String(req.query.status))}`);}const created=cfg.sortable?.created_at||'created_at';for(const field of ['from','to'])if(req.query[field]){const day=z.string().regex(/^\d{4}-\d{2}-\d{2}$/).parse(String(req.query[field]));where.push(field==='from'?`${created}>=${add(day)}::date`:`${created}<(${add(day)}::date + interval '1 day')`);}const sort=cfg.sortable?.[String(req.query.sort||'')]||cfg.defaultSort||created;const direction=req.query.direction==='asc'?'ASC':'DESC';values.push(limit,offset);return(await query(`SELECT ${cfg.select||['id',...cfg.fields].join(',')} FROM ${cfg.from||cfg.table} WHERE ${where.join(' AND ')} ORDER BY ${sort} ${direction} NULLS LAST LIMIT $${values.length-1} OFFSET $${values.length}`,values)).rows;}));
app.post('/admin/users',run(async req=>{admin(req);const user=z.object({name:z.string().trim().min(2).max(150),email:z.string().trim().email().max(254),username:z.string().regex(/^[A-Za-z0-9_.-]{3,40}$/),password:z.string().min(8).max(128),role:z.enum(['learner','hirer','admin'])}).parse(req.body);const hash=await bcrypt.hash(user.password,12);try{return(await query('INSERT INTO users(name,email,username,password_hash,role) VALUES($1,$2,$3,$4,$5) RETURNING id,name,email,username,role::text role,account_status::text account_status,created_at',[user.name,user.email,user.username,hash,user.role])).rows[0];}catch(error){if(error.code==='23505')throw new ApiError(409,'That email or username is already in use');throw error;}}));
app.post('/admin/:table/bulk',run(async req=>{const cfg=managedConfig(req);const body=z.object({ids:z.array(z.string().uuid()).min(1).max(100),action:z.enum(['status','delete']),status:z.string().optional()}).parse(req.body);if(body.action==='status'){if(!cfg.statusField||!cfg.statusValues?.includes(body.status))throw new ApiError(422,'This status is not available for the selected records');if(cfg.table==='users'&&body.ids.includes(req.user.sub)&&body.status!=='active')throw new ApiError(409,'You cannot disable your own admin account');const column=cfg.statusField.split('.').at(-1);const sets=[`${column}=$1`];const values=[cfg.table==='interest_categories'?body.status==='true':body.status,body.ids];if(cfg.table==='reported_showcase_posts'){sets.push('reviewed_by=$3','reviewed_at=now()');values.push(req.user.sub);}const result=await query(`UPDATE ${cfg.table} SET ${sets.join(',')} WHERE id=ANY($2::uuid[])`,values);return{updated:result.rowCount};}if(cfg.table==='users')throw new ApiError(409,'Suspend accounts instead of deleting user history');if(cfg.table==='showcase_posts'){const result=await query('UPDATE showcase_posts SET deleted_at=now() WHERE id=ANY($1::uuid[]) AND deleted_at IS NULL',[body.ids]);return{updated:result.rowCount};}const result=await query(`DELETE FROM ${cfg.table} WHERE id=ANY($1::uuid[])`,[body.ids]);return{updated:result.rowCount};}));
app.post('/admin/:table',upload.single('cover_image'),run(async req=>{const cfg=managedConfig(req);if(['users','showcase_posts','reported_showcase_posts','instructors'].includes(cfg.table))throw new ApiError(403,'Creation is not supported for this collection');const body=Object.fromEntries(cfg.fields.filter(key=>req.body[key]!==undefined).map(key=>[key,req.body[key]]));if(cfg.owner)body.creator_id=req.user.sub;if(cfg.table==='courses'){if(!body.instructor_id)throw new ApiError(422,'Assign an instructor before creating a course');body.instructor_id=uuid(body.instructor_id);if(!body.title||!body.slug||!body.description||!body.category_id)throw new ApiError(422,'Course title, slug, description, and interest are required');if(req.file){checkInstructorImage(req.file);body.cover_image=req.file.buffer;body.cover_image_mime_type=req.file.mimetype;}if(body.status==='published')body.published_at=new Date();}if(cfg.statusField&&body[cfg.statusField.split('.').at(-1)]!==undefined&&!cfg.statusValues?.includes(String(body[cfg.statusField.split('.').at(-1)])))throw new ApiError(422,'Invalid status');const keys=Object.keys(body);if(!keys.length)throw new ApiError(422,'No fields');return(await query(`INSERT INTO ${cfg.table}(${keys.join(',')}) VALUES(${keys.map((_,index)=>`$${index+1}`).join(',')}) RETURNING id`,Object.values(body))).rows[0];}));
app.patch('/admin/:table/:id',upload.single('cover_image'),run(async req=>{const cfg=managedConfig(req);uuid(req.params.id);const body=Object.fromEntries(cfg.fields.filter(key=>req.body[key]!==undefined).map(key=>[key,req.body[key]]));if(cfg.table==='courses'){if(body.instructor_id!==undefined)body.instructor_id=uuid(body.instructor_id);const removeCover=req.body.remove_cover_image;if(removeCover!==undefined&&!['true','false'].includes(removeCover))throw new ApiError(422,'Invalid remove cover flag');if(req.file){checkInstructorImage(req.file);body.cover_image=req.file.buffer;body.cover_image_mime_type=req.file.mimetype;}else if(removeCover==='true'){body.cover_image=null;body.cover_image_mime_type=null;}}if(cfg.table==='users'){if(body.role!==undefined&&!z.enum(['learner','hirer','moderator','admin']).safeParse(body.role).success)throw new ApiError(422,'Invalid user role');if(body.name!==undefined)body.name=z.string().trim().min(2).max(150).parse(body.name);if(body.email!==undefined)body.email=z.string().trim().email().max(254).parse(body.email);if(body.username!==undefined)body.username=z.string().regex(/^[A-Za-z0-9_.-]{3,40}$/).parse(body.username);if(body.account_status!==undefined)z.enum(['active','suspended','deactivated']).parse(body.account_status);if(req.params.id===req.user.sub&&(body.role&&body.role!=='admin'||body.account_status&&body.account_status!=='active'))throw new ApiError(409,'You cannot disable or demote your own admin account');}if(cfg.statusField&&body[cfg.statusField.split('.').at(-1)]!==undefined&&!cfg.statusValues?.includes(String(body[cfg.statusField.split('.').at(-1)])))throw new ApiError(422,'Invalid status');if(cfg.table==='courses'&&body.status==='published'&&body.published_at===undefined)body.published_at=new Date();if(cfg.table==='reported_showcase_posts'){body.reviewed_by=req.user.sub;body.reviewed_at=new Date();}const keys=Object.keys(body);if(!keys.length)throw new ApiError(422,'No fields');const values=[...Object.values(body),req.params.id];const result=await query(`UPDATE ${cfg.table} SET ${keys.map((key,index)=>`${key}=$${index+1}`).join(',')} WHERE id=$${keys.length+1}`,values);if(!result.rowCount)throw new ApiError(404,'Record not found');}));
app.delete('/admin/:table/:id',run(async req=>{const cfg=managedConfig(req);const id=uuid(req.params.id);if(cfg.table==='users')throw new ApiError(409,'Suspend accounts instead of deleting user history');if(cfg.table==='showcase_posts'){const result=await query('UPDATE showcase_posts SET deleted_at=now() WHERE id=$1 AND deleted_at IS NULL',[id]);if(!result.rowCount)throw new ApiError(404,'Record not found');return;}const result=await query(`DELETE FROM ${cfg.table} WHERE id=$1`,[id]);if(!result.rowCount)throw new ApiError(404,'Record not found');}));
app.get('/manage/courses/:id/materials',run(async req=>{admin(req);return(await query('SELECT id,name,type,sort_order,content_text,external_url,is_preview FROM course_materials WHERE course_id=$1 ORDER BY sort_order',[uuid(req.params.id)])).rows;}));
app.post('/manage/courses/:id/materials',run(async req=>{admin(req);const b=z.object({name:z.string().min(1).max(250),content_text:z.string().min(1),is_preview:z.boolean()}).parse(req.body);return tx(async db=>{await db.query('SELECT id FROM courses WHERE id=$1 FOR UPDATE',[uuid(req.params.id)]);return(await db.query(`INSERT INTO course_materials(course_id,name,type,content_text,is_preview,sort_order) VALUES($1,$2,'text',$3,$4,(SELECT coalesce(max(sort_order),-1)+1 FROM course_materials WHERE course_id=$1)) RETURNING id`,[req.params.id,b.name,b.content_text,b.is_preview])).rows[0];});}));
app.get('/manage/contests/:id/problems',run(async req=>{admin(req);return(await query('SELECT id,name,description,points FROM contest_problems WHERE contest_id=$1 ORDER BY sort_order',[uuid(req.params.id)])).rows;}));
app.post('/manage/contests/:id/problems',run(async req=>{admin(req);const b=z.object({name:z.string().min(1),description:z.string().min(1),points:z.number().nonnegative()}).parse(req.body);return tx(async db=>{await db.query('SELECT id FROM contests WHERE id=$1 FOR UPDATE',[uuid(req.params.id)]);return(await db.query(`INSERT INTO contest_problems(creator_id,contest_id,name,description,points,sort_order) VALUES($1,$2,$3,$4,$5,(SELECT coalesce(max(sort_order),-1)+1 FROM contest_problems WHERE contest_id=$2)) RETURNING id`,[req.user.sub,req.params.id,b.name,b.description,b.points])).rows[0];});}));
app.get('/manage/contests/:id/submissions',run(async req=>{admin(req);return(await query('SELECT s.id,s.content,s.score,s.status,s.problem_id,u.name FROM contest_submissions s JOIN users u ON u.id=s.participant_id WHERE contest_id=$1 ORDER BY submitted_at DESC LIMIT 100',[uuid(req.params.id)])).rows;}));
app.patch('/manage/submissions/:id',run(async req=>{admin(req);const b=z.object({score:z.number().nonnegative(),status:z.enum(['accepted','rejected','disqualified','judging'])}).parse(req.body);await tx(async db=>{const sub=(await db.query('SELECT contest_id,participant_id FROM contest_submissions WHERE id=$1',[uuid(req.params.id)])).rows[0];if(!sub)throw new ApiError(404,'Submission not found');await db.query('SELECT 1 FROM contest_participants WHERE contest_id=$1 AND participant_id=$2 FOR UPDATE',[sub.contest_id,sub.participant_id]);await db.query('UPDATE contest_submissions SET score=$1,status=$2,judged_at=now(),judged_by=$3 WHERE id=$4',[b.score,b.status,req.user.sub,req.params.id]);await db.query(`UPDATE contest_participants SET points=(SELECT coalesce(sum(best),0) FROM(SELECT max(score) best FROM contest_submissions WHERE contest_id=$1 AND participant_id=$2 AND status='accepted' GROUP BY problem_id) scores) WHERE contest_id=$1 AND participant_id=$2`,[sub.contest_id,sub.participant_id]);});}));
listen(app,process.env.FRONTEND_API_PORT||4010,'frontend-api');
